 pub fn recover_close_original_step<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::native_decoding::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::native_decoding::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{let target=self.close_target.ok_or_else(||ValueError::invariant("default close target absent"))?;self.bind_close_action(effect,true,target,Some(&mut *original),body)?;if self.close_reply.is_some(){return self.record_close_reply(effect,reply)}let g=effect.grant();let remaining=effect.remaining_work_units()?.checked_sub(1).ok_or_else(||ValueError::literal(crate::ValueRefusalKind::WorkLimit,"default original close reply lacks its reserved work"))?;let copy=Self::close_reply_demand().copy_bytes;let grant=if target==1{child_grant(g,copy)}else{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.checked_sub(copy).ok_or_else(invalid)?,..g}};{let mut child=effect.reborrow(grant,remaining)?;let inner=crate::native_decoding::OriginalEffectReply::borrow(&mut self.close_reply)?;match target{1=>{let cursor=self.cursor.get_mut().filter(|cursor|!cursor.terminal_is_empty()&&cursor.requires_original_control()).ok_or_else(||ValueError::literal(crate::ValueRefusalKind::UnsupportedOwner,"default original close child changed"))?;drop(cursor.recover_close_original_step(original,body.saturating_sub(copy),&mut child,inner)?)},2=>drop(self.retirement.recover_step_original_into(original,body.saturating_sub(copy),&mut child,inner)?),_=>return Err(ValueError::invariant("default original close target changed"))}}self.record_close_reply(effect,reply)}
 pub fn terminal_is_empty(&self)->bool{self.cursor.terminal_is_empty()&&self.retired_header.is_none()&&self.output.is_none()&&self.retirement.is_empty()&&self.action.terminal_is_empty()&&self.authority.is_none()&&self.close_reply.is_none()&&self.close_action.is_none()&&self.close_target.is_none()&&self.close_origin.is_none()&&self.close_body.is_none()&&self.close_grant.is_none()&&self.close_loan.is_none()}
