impl<T:NativeDefault> Default for NativeDefaultSlot<T>{fn default()->Self{Self::new()}}
impl<T:NativeDefault> Drop for NativeDefaultSlot<T>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"native default slot requires funded closure");if empty{unsafe{ManuallyDrop::drop(&mut self.output);ManuallyDrop::drop(&mut self.authority);ManuallyDrop::drop(&mut self.close_reply);}}}}
